# Display only: not executable, not round-trippable; toke semantics apply.
# Key: T!E -> Result[T, E]; x!E -> propagate(x, E); '# mut' marks a mutable
# binding; _fnN/_ifN/_mtN are a closure, if or mt lifted out of an expression;
# fixed-width types other than i64/f64 keep their toke names (i32, u8, f32).

# module datapipe.main
import std.io as io
import std.file as file
import std.csv as csv
import std.str as str
import std.args as args


@dataclass
class colstats:
    name: str
    count: u64
    sum: float
    min: float
    max: float
    avg: float


@dataclass
class report:
    filename: str
    rows: u64
    columns: u64
    stats: list[colstats]


def cell(rows: list[csvrow], r: int, c: int) -> str:
    row = rows[r + 1]
    return row.fields[c]


def isnumeric(s: str) -> bool:
    t = str.trim(s)
    if str.len(t) == 0:
        return False
    match str.tofloat(t):
        case ok(x):
            return True
        case err(e):
            return False


def tofloat(s: str) -> float:
    match str.tofloat(str.trim(s)):
        case ok(x):
            v = x
        case err(e):
            v = 0.0
    return v


def iscolnumeric(rows: list[csvrow], c: int, ndata: int) -> bool:
    allnum = True  # mut
    any = False  # mut
    r = 0
    while r < ndata:
        v = str.trim(cell(rows, r, c))
        if str.len(v) > 0:
            any = True
            if isnumeric(v) == False:
                allnum = False
        r = r + 1
    if any == False:
        return False
    return allnum


def computecol(rows: list[csvrow], c: int, ndata: int, name: str) -> colstats:
    count = 0  # mut
    sum = 0.0  # mut
    mn = 0.0  # mut
    mx = 0.0  # mut
    first = True  # mut
    r = 0
    while r < ndata:
        v = str.trim(cell(rows, r, c))
        if str.len(v) > 0:
            num = tofloat(v)
            count = count + 1
            sum = sum + num
            if first:
                mn = num
                mx = num
                first = False
            else:
                if num < mn:
                    mn = num
                if num > mx:
                    mx = num
        r = r + 1
    avg = 0.0  # mut
    if count > 0:
        avg = sum / float(count)
    return colstats(name=name, count=u64(count), sum=sum, min=mn, max=mx, avg=avg)


def printstats(s: colstats) -> int:
    io.println(str.concat("  ", str.concat(s.name, str.concat(" (count ", str.concat(str.fromint(int(s.count)), ")")))))
    io.println(str.concat("    sum=", str.format(s.sum, "%.2f")))
    io.println(str.concat("    avg=", str.format(s.avg, "%.2f")))
    io.println(str.concat("    min=", str.format(s.min, "%.2f")))
    io.println(str.concat("    max=", str.format(s.max, "%.2f")))
    return 0


def colstatstojson(s: colstats) -> str:
    buf = str.buf()
    str.add(buf, "{\"name\":\"")
    str.add(buf, s.name)
    str.add(buf, "\",\"count\":")
    str.add(buf, str.fromint(int(s.count)))
    str.add(buf, ",\"sum\":")
    str.add(buf, str.format(s.sum, "%.2f"))
    str.add(buf, ",\"min\":")
    str.add(buf, str.format(s.min, "%.2f"))
    str.add(buf, ",\"max\":")
    str.add(buf, str.format(s.max, "%.2f"))
    str.add(buf, ",\"avg\":")
    str.add(buf, str.format(s.avg, "%.2f"))
    str.add(buf, "}")
    return str.done(buf)


def reporttojson(r: report) -> str:
    buf = str.buf()
    str.add(buf, "{\"filename\":\"")
    str.add(buf, r.filename)
    str.add(buf, "\",\"rows\":")
    str.add(buf, str.fromint(int(r.rows)))
    str.add(buf, ",\"columns\":")
    str.add(buf, str.fromint(int(r.columns)))
    str.add(buf, ",\"stats\":[")
    i = 0
    while i < int(r.stats.len):
        if i > 0:
            str.add(buf, ",")
        str.add(buf, colstatstojson(r.stats[i]))
        i = i + 1
    str.add(buf, "]}")
    return str.done(buf)


def usage() -> int:
    io.eprintln("usage: datapipe <input.csv> <output.json>")
    return 2


def main() -> int:
    match args[1]:
        case ok(v):
            path = v
        case err(e):
            return usage()
    match args[2]:
        case ok(v):
            output = v
        case err(e):
            return usage()
    match file.read(path):
        case ok(v):
            raw = v
        case err(e):
            raw = ""
    if str.len(raw) == 0:
        io.eprintln(str.concat("cannot read file: ", path))
        return 2
    match csv.parse(str.bytes(raw)):
        case ok(v):
            rows = v
        case err(e):
            rows = []
    if rows.len < 2:
        io.eprintln("no data rows in csv")
        return 2
    headers = rows[0].fields
    ncols = int(headers.len)
    ndata = int(rows.len) - 1
    stats = []  # mut
    c = 0
    while c < ncols:
        if iscolnumeric(rows, c, ndata):
            stats = stats.push(computecol(rows, c, ndata, headers[c]))
        c = c + 1
    io.println(str.concat("file:    ", path))
    io.println(str.concat("rows:    ", str.fromint(ndata)))
    io.println(str.concat("columns: ", str.fromint(ncols)))
    io.println("")
    io.println("numeric column statistics:")
    i = 0
    while i < int(stats.len):
        printstats(stats[i])
        i = i + 1
    report = report(filename=path, rows=u64(ndata), columns=u64(ncols), stats=stats)
    jsonstr = reporttojson(report)
    match file.write(output, jsonstr):
        case ok(v):
            io.println(str.concat("\nreport written to: ", output))
        case err(e):
            io.eprintln(str.concat("error writing report: ", output))
    return 0
